'use client';

import { useState } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { AskBar } from './ask-bar';
import { PERSON, WORKSPACE } from './data';
import { Figures } from './figures';
import { NeedsYou } from './needs-you';
import { QuickActions } from './quick-actions';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  waitingCountOf,
} from './session';
import { SpendCard, TasksCard } from './trend-cards';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

export default function AiProduct02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  useKeptHeight(ref);
  const shouldReduceMotion = usePrefersReducedMotion();
  const [hasRolled, setHasRolled] = useState(false);
  if (isInView && !hasRolled) {
    setHasRolled(true);
  }
  const isRolled = hasRolled || shouldReduceMotion;
  const waiting = waitingCountOf(state);
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;
  const isStreaming = !shouldReduceMotion;

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container min-h-[88rem] w-full @3xl:min-h-[50rem]'
    >
      <div className='mx-auto flex max-w-5xl flex-col gap-5 px-4 py-6 @2xl:px-6 @2xl:py-8'>
        <header className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
          <div className='flex min-w-0 items-center gap-2.5'>
            <CompanyMark seed={WORKSPACE.name} size='lg' />
            <div className='flex min-w-0 flex-col'>
              <h1 className='truncate text-lg font-semibold'>Home</h1>
              <p className='text-muted-foreground flex items-center gap-1.5 text-xs'>
                {WORKSPACE.name}
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
          </div>
          <div className='flex items-center gap-3'>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
            <span className='flex items-center gap-2 text-[13px]'>
              <Avatar seed={PERSON.name} className='size-7' />
              {PERSON.name}
            </span>
          </div>
        </header>

        <Figures isRolled={isRolled} waiting={waiting} />

        <AskBar
          question={state.question}
          answerId={state.answerId}
          isStreaming={isStreaming}
          pressed={pressed}
          onType={(text) => act({ type: 'questionTyped', text })}
          onAsk={() => act({ type: 'asked' })}
          onPick={(id) => act({ type: 'suggestionPicked', id })}
        />

        <QuickActions />

        <div className='grid gap-5 @3xl:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)] @3xl:items-start'>
          <NeedsYou
            arrived={state.arrived}
            resolved={state.resolved}
            waiting={waiting}
            pressed={pressed}
            onAct={(id) => act({ type: 'resolved', id })}
          />
          <div className='flex flex-col gap-5'>
            <SpendCard isRolled={isRolled} />
            <TasksCard isRolled={isRolled} />
          </div>
        </div>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';

import { TODAY } from './data';

const MONEY: Intl.NumberFormatOptions = {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

function shownOf(isRolled: boolean, value: number) {
  if (isRolled) {
    return value;
  }
  return 0;
}

type FigureProps = {
  label: string;
  children: React.ReactNode;
};

function Figure({ label, children }: FigureProps) {
  return (
    <li className='bg-foreground/[0.03] flex min-w-0 flex-col gap-1 rounded-xl p-4'>
      <p className='text-muted-foreground truncate text-[13px]'>{label}</p>
      <p className='flex text-2xl font-semibold'>{children}</p>
    </li>
  );
}

type FiguresProps = {
  /** The counts roll up from zero the first time the page is seen. */
  isRolled: boolean;
  waiting: number;
};

export function Figures({ isRolled, waiting }: FiguresProps) {
  return (
    <ul aria-label='Today' className='grid grid-cols-2 gap-3 @3xl:grid-cols-4'>
      <Figure label='Runs today'>
        <MotionNumber value={shownOf(isRolled, TODAY.runs)} />
      </Figure>
      <Figure label='Tasks finished'>
        <MotionNumber value={shownOf(isRolled, TODAY.finished)} />
      </Figure>
      <Figure label='Waiting on you'>
        <MotionNumber value={waiting} />
      </Figure>
      <Figure label='Spent today'>
        <MotionNumber
          value={shownOf(isRolled, TODAY.spentUsd)}
          prefix='$'
          format={MONEY}
        />
      </Figure>
    </ul>
  );
}

'use client';

import { useId } from 'react';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';
import { StreamedInk } from '@/registry/ndeko/ui/streamed-text';

import { answerTextOf, SUGGESTIONS, type SuggestionId } from './data';
import type { AnswerId } from './session';

const WORD_MS = 38;

type AskBarProps = {
  question: string;
  answerId: AnswerId | null;
  isStreaming: boolean;
  pressed: string | null;
  onType: (text: string) => void;
  onAsk: () => void;
  onPick: (id: SuggestionId) => void;
};

export function AskBar({
  question,
  answerId,
  isStreaming,
  pressed,
  onType,
  onAsk,
  onPick,
}: AskBarProps) {
  const fieldId = useId();
  const answerRegionId = useId();
  const hasAnswer = answerId !== null;

  function ask(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onAsk();
  }

  return (
    <section aria-label='Ask' className='flex flex-col gap-3'>
      <form onSubmit={ask} className='flex items-center gap-2'>
        <div className='relative min-w-0 flex-1'>
          <label htmlFor={fieldId} className='sr-only'>
            Ask about your runs, tasks and spend
          </label>
          <SearchIcon className='text-muted-foreground pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2' />
          <Input
            id={fieldId}
            autoComplete='off'
            placeholder='Ask about your runs, tasks and spend'
            value={question}
            aria-controls={answerRegionId}
            onChange={(event) => onType(event.target.value)}
            className='h-10 rounded-lg ps-9'
          />
        </div>
        <Button
          type='submit'
          size='lg'
          className={cn('h-10 shrink-0', pressedSolidOf(pressed === 'ask'))}
        >
          Ask
        </Button>
      </form>
      <ul aria-label='Suggested questions' className='flex flex-wrap gap-1.5'>
        {SUGGESTIONS.map((suggestion) => (
          <li key={suggestion.id}>
            <Button
              type='button'
              variant='outline'
              size='sm'
              onClick={() => onPick(suggestion.id)}
            >
              {suggestion.label}
            </Button>
          </li>
        ))}
      </ul>
      <Fold open={hasAnswer} id={answerRegionId}>
        {hasAnswer && (
          <div className='bg-foreground/[0.04] flex flex-col gap-1 rounded-lg p-3'>
            <p className='text-muted-foreground text-xs'>Answer</p>
            <p
              key={answerId}
              className='max-w-prose text-[13px] leading-relaxed text-pretty'
            >
              <StreamedInk
                text={answerTextOf(answerId)}
                isStreaming={isStreaming}
                wordMs={WORD_MS}
              />
            </p>
          </div>
        )}
      </Fold>
    </section>
  );
}

import {
  BotIcon,
  PlugIcon,
  PlusIcon,
  UserRoundPlusIcon,
} from '@/registry/ndeko/lib/icons';

import { ACTIONS, type ActionId, type QuickAction } from './data';

const GLYPHS: Record<ActionId, typeof PlusIcon> = {
  task: PlusIcon,
  agent: BotIcon,
  app: PlugIcon,
  invite: UserRoundPlusIcon,
};

function ActionTile({ action }: { action: QuickAction }) {
  const Glyph = GLYPHS[action.id];

  return (
    <a
      href='#'
      className='bg-foreground/[0.03] hover:bg-foreground/[0.05] focus-visible:ring-ring/25 flex items-center gap-3 rounded-xl p-3 transition-[background-color,scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-[3px] active:scale-[0.97]'
    >
      <span
        aria-hidden='true'
        className='keycap-3d text-muted-foreground inline-flex size-8 shrink-0 items-center justify-center rounded-lg'
      >
        <Glyph className='size-4' />
      </span>
      <span className='flex min-w-0 flex-col'>
        <span className='truncate text-[13px] font-medium'>{action.label}</span>
        <span className='text-muted-foreground truncate text-xs'>
          {action.hint}
        </span>
      </span>
    </a>
  );
}

export function QuickActions() {
  return (
    <ul
      aria-label='Quick actions'
      className='grid gap-3 @lg:grid-cols-2 @4xl:grid-cols-4'
    >
      {ACTIONS.map((action) => (
        <li key={action.id}>
          <ActionTile action={action} />
        </li>
      ))}
    </ul>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { WAITING, type Waiting, type WaitingId } from './data';

function toneOf(isDone: boolean) {
  if (isDone) {
    return 'opacity-60';
  }
  return undefined;
}

function waitingVariantOf(waiting: number) {
  if (waiting === 0) {
    return 'secondary';
  }
  return 'warning';
}

function stateKeyOf(isDone: boolean) {
  if (isDone) {
    return 'done';
  }
  return 'open';
}

type RowProps = {
  waiting: Waiting;
  isDone: boolean;
  pressed: string | null;
  onAct: (id: WaitingId) => void;
};

function WaitingRow({ waiting, isDone, pressed, onAct }: RowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const isPressed = pressed === `act-${waiting.id}`;

  return (
    <motion.li className='overflow-hidden' {...presence}>
      <div className='grid grid-cols-[auto_minmax(0,1fr)] items-center gap-x-3 gap-y-2 px-1 py-2.5 @md:grid-cols-[auto_minmax(0,1fr)_auto]'>
        <MeshTile
          seed={waiting.agent}
          color={seriesColorOf(waiting.series)}
          size='lg'
        />
        <div
          className={cn(
            'flex min-w-0 flex-1 flex-col gap-0.5 transition-opacity duration-200',
            toneOf(isDone)
          )}
        >
          <p className='flex items-baseline gap-2 text-[13px] font-medium'>
            {waiting.agent}
            <span className='text-muted-foreground text-xs font-normal tabular-nums'>
              {waiting.waited}
            </span>
          </p>
          <p className='text-muted-foreground text-xs text-pretty'>
            {waiting.ask}
          </p>
        </div>
        <Swap
          swapKey={stateKeyOf(isDone)}
          className='col-start-2 justify-self-start @md:col-start-auto @md:justify-self-end'
        >
          {!isDone && (
            <Button
              type='button'
              size='sm'
              variant='outline'
              onClick={() => onAct(waiting.id)}
              className={pressedQuietOf(isPressed)}
            >
              {waiting.action}
            </Button>
          )}
          {isDone && (
            <span className='text-success-foreground flex items-center gap-1.5 text-xs font-medium'>
              <DrawnCheck tone='success' entrance='draw' />
              {waiting.done}
            </span>
          )}
        </Swap>
      </div>
    </motion.li>
  );
}

type NeedsYouProps = {
  arrived: number;
  resolved: WaitingId[];
  waiting: number;
  pressed: string | null;
  onAct: (id: WaitingId) => void;
};

export function NeedsYou({
  arrived,
  resolved,
  waiting,
  pressed,
  onAct,
}: NeedsYouProps) {
  const rows = WAITING.slice(0, arrived);
  const isNobodyWaiting = waiting === 0;

  return (
    <section
      aria-label='Agents that need you'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-2 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:p-5'
    >
      <header className='flex items-center justify-between gap-3'>
        <h2 className='text-sm font-medium'>Needs you</h2>
        <Badge variant={waitingVariantOf(waiting)}>
          <MotionNumber value={waiting} />
          waiting
        </Badge>
      </header>
      <ul className='flex flex-col'>
        <AnimatePresence initial={false}>
          {rows.map((row) => (
            <WaitingRow
              key={row.id}
              waiting={row}
              isDone={resolved.includes(row.id)}
              pressed={pressed}
              onAct={onAct}
            />
          ))}
        </AnimatePresence>
      </ul>
      {isNobodyWaiting && (
        <p className='text-muted-foreground py-6 text-center text-[13px]'>
          Nothing is waiting on you
        </p>
      )}
    </section>
  );
}

'use client';

import type { CSSProperties } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import { SPEND, TASKS_DONE, WEEK_DAYS } from './data';

const STAGGER_MS = 60;

function easedOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return 'transition-none';
  }
  return 'transition-transform duration-700 ease-(--ease-out-strong)';
}

function tallestOf(values: readonly number[]) {
  return Math.max(1, ...values);
}

function barStyleOf(
  value: number,
  tallest: number,
  isRolled: boolean,
  index: number
): CSSProperties {
  let share = 0;
  if (isRolled) {
    share = value / tallest;
  }
  const delay = index * STAGGER_MS;
  return { transform: `scaleY(${share})`, transitionDelay: `${delay}ms` };
}

function barToneOf(isToday: boolean) {
  if (isToday) {
    return 'bg-primary';
  }
  return 'bg-primary/35';
}

type MiniBarsProps = {
  values: readonly number[];
  isRolled: boolean;
  caption: string;
  unit: string;
};

function MiniBars({ values, isRolled, caption, unit }: MiniBarsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);
  const tallest = tallestOf(values);
  const lastIndex = values.length - 1;

  return (
    <div className='relative flex flex-col gap-1.5'>
      <div aria-hidden='true' className='flex h-16 items-stretch gap-1.5'>
        {values.map((value, index) => (
          <span
            key={WEEK_DAYS[index]}
            className='bg-foreground/[0.04] relative flex-1 overflow-hidden rounded-[3px]'
          >
            <span
              style={barStyleOf(value, tallest, isRolled, index)}
              className={cn(
                'absolute inset-0 origin-bottom',
                eased,
                barToneOf(index === lastIndex)
              )}
            />
          </span>
        ))}
      </div>
      <div aria-hidden='true' className='flex gap-1.5'>
        {WEEK_DAYS.map((day) => (
          <span
            key={day}
            className='text-muted-foreground flex-1 text-center text-[11px]'
          >
            {day}
          </span>
        ))}
      </div>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={WEEK_DAYS[index]}>
                <th scope='row'>{WEEK_DAYS[index]}</th>
                <td>
                  {value} {unit}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function shownOf(isRolled: boolean, value: number) {
  if (isRolled) {
    return value;
  }
  return 0;
}

function meterStyleOf(share: number, isRolled: boolean): CSSProperties {
  let shown = 0;
  if (isRolled) {
    shown = share;
  }
  const open = 1 - shown;
  const remaining = open * 100;
  return { transform: `translateX(-${remaining}%)` };
}

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:p-5';

type TrendCardProps = {
  isRolled: boolean;
};

export function SpendCard({ isRolled }: TrendCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);
  const share = SPEND.usedUsd / SPEND.budgetUsd;
  const meterStyle = meterStyleOf(share, isRolled);

  return (
    <section aria-label='Spend against budget' className={CARD}>
      <header className='flex flex-col gap-1'>
        <h3 className='text-muted-foreground text-[13px] font-medium'>
          Spend this month
        </h3>
        <p className='flex items-baseline gap-2'>
          <MotionNumber
            value={shownOf(isRolled, SPEND.usedUsd)}
            prefix='$'
            className='text-2xl font-semibold'
          />
          <span className='text-muted-foreground text-[13px] tabular-nums'>
            of ${SPEND.budgetUsd} budget
          </span>
        </p>
      </header>
      <div
        role='meter'
        aria-label='Budget used'
        aria-valuemin={0}
        aria-valuemax={SPEND.budgetUsd}
        aria-valuenow={SPEND.usedUsd}
        className='bg-foreground/[0.06] h-1.5 overflow-hidden rounded-full'
      >
        <span
          style={meterStyle}
          className={cn('bg-primary block h-full rounded-full', eased)}
        />
      </div>
      <MiniBars
        values={SPEND.byDay}
        isRolled={isRolled}
        caption='Dollars spent by day this week, illustrative'
        unit='dollars'
      />
    </section>
  );
}

export function TasksCard({ isRolled }: TrendCardProps) {
  return (
    <section aria-label='Tasks done this week' className={CARD}>
      <header className='flex flex-col gap-1'>
        <h3 className='text-muted-foreground text-[13px] font-medium'>
          Tasks done this week
        </h3>
        <p className='flex'>
          <MotionNumber
            value={shownOf(isRolled, TASKS_DONE.total)}
            className='text-2xl font-semibold'
          />
        </p>
      </header>
      <MiniBars
        values={TASKS_DONE.byDay}
        isRolled={isRolled}
        caption='Tasks done by day this week, illustrative'
        unit='tasks'
      />
    </section>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import {
  answerTextOf,
  SUGGESTIONS,
  suggestionOf,
  WAITING,
  type SuggestionId,
  type WaitingId,
} from './data';

export type AnswerId = SuggestionId | 'none';

export type HomeState = {
  question: string;
  answerId: AnswerId | null;
  /** How many of the agents have stopped to ask for the person. They arrive in the order of the list. */
  arrived: number;
  resolved: WaitingId[];
  spoken: string;
};

export type HomeAction =
  | { type: 'arrived' }
  | { type: 'questionTyped'; text: string }
  | { type: 'asked' }
  | { type: 'suggestionPicked'; id: SuggestionId }
  | { type: 'resolved'; id: WaitingId };

type Step = SessionStep<HomeState, HomeAction>;

export const INITIAL: HomeState = {
  question: '',
  answerId: null,
  arrived: 0,
  resolved: [],
  spoken: '',
};

export function waitingCountOf(state: HomeState) {
  return state.arrived - state.resolved.length;
}

function arrived(state: HomeState): HomeState {
  if (state.arrived >= WAITING.length) {
    return state;
  }
  const next = WAITING[state.arrived];
  const spoken = `${next.agent} needs you: ${next.ask}`;
  return { ...state, arrived: state.arrived + 1, spoken };
}

function questionTyped(state: HomeState, text: string): HomeState {
  return { ...state, question: text, answerId: null };
}

function asked(state: HomeState): HomeState {
  const isEmpty = state.question.trim() === '';
  if (isEmpty) {
    return state;
  }
  const match = suggestionOf(state.question);
  const answerId: AnswerId = match?.id ?? 'none';
  const spoken = answerTextOf(answerId);
  return { ...state, answerId, spoken };
}

function suggestionPicked(state: HomeState, id: SuggestionId): HomeState {
  const suggestion = SUGGESTIONS.find((candidate) => candidate.id === id);
  if (!suggestion) {
    return state;
  }
  return {
    ...state,
    question: suggestion.question,
    answerId: id,
    spoken: suggestion.answer,
  };
}

function resolved(state: HomeState, id: WaitingId): HomeState {
  const index = WAITING.findIndex((waiting) => waiting.id === id);
  const hasArrived = index >= 0 && index < state.arrived;
  const isDone = state.resolved.includes(id);
  if (!hasArrived || isDone) {
    return state;
  }
  const spoken = WAITING[index].done;
  return { ...state, resolved: [...state.resolved, id], spoken };
}

export function reducer(state: HomeState, action: HomeAction): HomeState {
  switch (action.type) {
    case 'arrived':
      return arrived(state);
    case 'questionTyped':
      return questionTyped(state, action.text);
    case 'asked':
      return asked(state);
    case 'suggestionPicked':
      return suggestionPicked(state, action.id);
    case 'resolved':
      return resolved(state, action.id);
  }
}

const KEY_MS = 42;

function typingSteps(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'questionTyped', text: typed },
  }));
}

function arrivalAfterOf(index: number) {
  if (index === 0) {
    return 900;
  }
  return 750;
}

/** The agents arrive on their own, so they keep arriving after a person takes over. */
const ARRIVALS: Step[] = WAITING.map((_, index) => ({
  after: arrivalAfterOf(index),
  action: { type: 'arrived' },
}));

